mapper.select:
SELECT s.*, p.project_name, u.real_name as leader_name FROM project_settlement s LEFT JOIN research_project p ON s.project_id = p.id LEFT JOIN sys_user u ON p.leader_id = u.id WHERE 1=1
AND p.project_name LIKE CONCAT('%',#{keyword},'%')
AND s.status = #{status}
AND p.leader_id = #{leaderId}
ORDER BY s.create_time DESC
